import std.io
import std.collections

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let m = collections.mapOf(["aa", "bb", "cc"], [1, 2, 3])
    m.put("bb", 20)
    match m.remove("aa") {
        Some(v) => { io.println("rm:${v}") }
        None => { io.println("rm:none") }
    }
    m.put("aa", 100)
    match m.get("aa") {
        Some(v) => { io.println("aa:${v}") }
        None => { io.println("aa:none") }
    }
    match m.get("bb") {
        Some(v) => { io.println("bb:${v}") }
        None => { io.println("bb:none") }
    }
    match m.get("zz") {
        Some(v) => { io.println("zz:${v}") }
        None => { io.println("zz:none") }
    }
    io.println("size:${m.size()}")
    return Ok(())
}
